  "explanation": "Artera cerebrală medie stângă — Incorect: ACM stângă produce hemipareză dreaptă predominant facio-brahială și afazie, nu deficit stâng cu neglijare.\n\nArtera cerebrală medie dreaptă — Corect: Tabelul indică pentru ACM dreaptă hemipareză stângă facio-brahială, neglijare vizuală și senzorială și negarea dizabilității.\n\nArtera cerebrală posterioară dreaptă — Incorect: ACP produce hemianopsie homolaterală și deficite talamice/occipito-parietale, nu hemipareză facio-brahială cu neglijare.\n\nCapsula internă dreaptă (artere lenticulostriate) — Incorect: Infarctul capsulei interne dă hemisindrom motor egal față = membru superior = membru inferior, fără afazie sau alte semne corticale; neglijarea este semn cortical.\n\nBulbul lateral drept (artera cerebeloasă postero-inferioară) — Incorect: Bulbul lateral (Wallenberg) produce sindrom Horner ipsilateral, vertij, disfagie, ataxie și hipoestezie spino-talamică controlaterală.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 26, p. 841, 840, Infarctul cerebral — Sindroame clinice de AVC (Cadranul 26.35) (pagini PDF: 145, 144).",
