  "explanation": "Este responsabilă pentru aproximativ 25% din AVC-uri, cu o mortalitate similară AVC ischemic — Incorect: Textul precizează că hemoragia intracerebrală reprezintă aproximativ 10% din AVC-uri și are mortalitate mai mare decât AVC ischemic (până la 50%).\n\nÎn hipertensiune, ruptura microanevrismelor Charcot-Bouchard (0,8–1,0 mm) produce hemoragii masive în ganglionii bazali, punte, cerebel și substanța albă subcorticală — Corect: Microanevrismele Charcot-Bouchard au 0,8–1,0 mm și ruptura lor produce hemoragii de obicei masive în ganglionii bazali, punte, cerebel și substanța albă subcorticală.\n\nAngiopatia amiloidă cerebrală produce hemoragie lobară, adesea recurentă, la pacienți normotensivi, în special peste 60 de ani — Corect: Angiopatia amiloidă cerebrală cauzează hemoragie intracerebrală lobară (în special parietal/occipital), deseori recurentă, la normotensivi peste 60 de ani.\n\nAngiopatia amiloidă cerebrală este asociată cu genotipul E4 al apolipoproteinei E și este mai frecventă la pacienții cu boală Parkinson — Incorect: Textul indică asocierea cu genotipul E2 al apolipoproteinei E și frecvența crescută la pacienții cu boală Alzheimer, nu Parkinson.\n\nMalformațiile arteriovenoase, cavernoamele, anevrismele și trombozele durale venoase cauzează aproximativ 20% dintre hemoragiile intracerebrale — Corect: Textul precizează că MAV, cavernoamele, anevrismele și trombozele durale venoase cauzează aproximativ 20% dintre hemoragiile intracerebrale.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 26, p. 845, 846, Hemoragia intracraniană — Hemoragia intracerebrală: etiologie (pagini PDF: 149, 150).",
