  "explanation": "La vârsta >50 de ani sau imunocompromis se adaugă ampicilină pentru a acoperi Listeria — Corect: Cadranul 26.59: +ampicilină pentru Listeria dacă >50 ani sau imunocompromis.\n\nAntibioticele se continuă cel puțin 5 zile; dexametazonă 0,6 mg/kg i.v. 4 zile, cu sau înaintea primei doze — Corect: Minim 5 zile; dexametazonă 0,6 mg/kg 4 zile.\n\nÎn TBM, etambutolul trebuie evitat din cauza complicațiilor oculare; tratamentul prezumtiv (rifampicină, izoniazidă, pirazinamidă) cel puțin 9 luni — Corect: Etambutol evitat; 9 luni rifampicină/izoniazidă/pirazinamidă.\n\nEtambutolul este de elecție în TBM pentru că protejează nervul optic — Incorect: Etambutolul se evită tocmai pentru complicațiile oculare.\n\nListeria se acoperă cu vancomicină orală, ampicilina fiind evitată după 50 de ani — Incorect: Listeria se acoperă cu ampicilină (sau cotrimoxazol la alergie), nu cu vancomicină orală.\n\nReferință: Kumar & Clark, Medicină clinică, ediția a 10-a, text român, cap. 26, p. 871, 869, Meningita — Listeria/ampicilină, 5 zile, TBM fără etambutol (pagini PDF: 156, 154).",
